('u', 518, 24477, NULL, 'Scourge Javelin Rocket', 'A small rocket with a piercing warhead.\r\n\r\nA modified version of the Trauma rocket. It can reach higher velocity than the Trauma rocket but needs to reduce the speed of the ship to compensate.', NULL, NULL, NULL, NULL, NULL, NULL, 57320, NULL, NULL, NULL, NULL, NULL),
('u', 518, 24478, NULL, 'Nova Javelin Rocket', 'A small rocket with a nuclear warhead.\r\n\r\nA modified version of the Nova rocket. It can reach higher velocity than the Nova rocket but needs to reduce the speed of the ship to compensate.', NULL, NULL, NULL, NULL, NULL, NULL, 57320, NULL, NULL, NULL, NULL, NULL),
