('u', 512, 520, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60591.4, NULL, NULL, NULL, NULL, NULL),
('u', 516, 521, NULL, NULL, 'Utilizes a combination of containment field emitters and redundancy systems to prevent critical system damage. \n\n\n\nGrants a bonus to resistance for shield, armor and hull.\n\n\n\nOnly one Damage Control can be activated at a given time.', NULL, NULL, NULL, NULL, NULL, NULL, 5111.05, NULL, NULL, NULL, NULL, NULL),
('u', 512, 522, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5668.75, NULL, NULL, NULL, NULL, NULL),
