('u', 516, 2587, NULL, NULL, 'A backup system which operates in conjunction with the main array. Reduces the ship\'s vulnerability to jamming.\n\n\n\nPenalty: Using more than one type of this module or similar modules that affect the same attribute on the ship will be penalized.', NULL, NULL, NULL, NULL, NULL, NULL, 38396.1, NULL, NULL, NULL, NULL, NULL),
('u', 516, 2588, NULL, NULL, 'A backup system which operates in conjunction with the main array. Reduces the ship\'s vulnerability to jamming.\n\n\n\nPenalty: Using more than one type of this module or similar modules that affect the same attribute on the ship will be penalized.', NULL, NULL, NULL, NULL, NULL, NULL, 660958, NULL, NULL, NULL, NULL, NULL),
('u', 518, 2589, NULL, 'Hardwiring - Genolution Core Augmentation CA-2', '<br><br><font color="yellow"><b>Traits</b></font><br>Slot 4<br>Boost intelligence by 3<br>Provides +1.5% CPU bonus<br>Provides +1.5% capacitor recharge<br>Implant set bonus: 50%<br><br><font color="yellow"><b>Development</b></font><br>This is the second half of the Core Augmentation implant set, delivered by Genolution as a follow-up to the CA-1 just months after their first demonstration of new augmentation techniques shook up the often-stagnant industry.<br><br>The CA-2 picks up where its predecessor left off, providing a dual boost via frontal lobe enhancements and a neocortical modification that complements the CA-1\'s focus on a captain', NULL, NULL, NULL, NULL, NULL, NULL, 4464.63, NULL, NULL, NULL, NULL, NULL),
('u', 516, 2591, NULL, NULL, 'A backup system which operates in conjunction with the main array. Reduces the ship\'s vulnerability to jamming.\n\n\n\nPenalty: Using more than one type of this module or similar modules that affect the same attribute on the ship will be penalized.', NULL, NULL, NULL, NULL, NULL, NULL, 74112.5, NULL, NULL, NULL, NULL, NULL),
