INSERT INTO `cs_invTypes` (`op`, `mask`, `typeID`, `groupID`, `typeName`, `description`, `graphicID`, `radius`, `mass`, `volume`, `capacity`, `raceID`, `basePrice`, `published`, `marketGroupID`, `soundID`, `iconID`, `dataID`) VALUES
('u', 4, 11586, NULL, NULL, 'Written by the Heideran VII, the Amarr Emperor himself, Pax Amarria is the most remarkable book published in the last century. In it the Emperor writes about his hopes and dreams for peace throughout the galaxy; a vision that has propelled him into becoming the champion of improved international relations. His relentless strive for these goals has brought unparalleled harmony in the relationship between the empires; his constant search for peaceful solutions to any problem having many times becalmed brewing storm.\n\n\n\nThis is a signed copy, with Heideran\'s signature at the front: "Semper Pax. Heideran VII".', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('u', 512, 11588, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90372.4, NULL, NULL, NULL, NULL, NULL),
('u', 4, 11597, NULL, NULL, 'This is the infamous leader of a small pirate raiding party which has been terrorizing various sectors throughout the known universe.  His most notable offences include high-profile kidnappings.  His victims are either sold as slaves or for ransom.  Threat level: Extreme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
