('u', 516, 21542, NULL, NULL, 'A tiny launcher that can carry a very limited supply of rockets. Not really intended as a primary weapon but rather as a cheap supplementary weapon system.\n\n\n\nMust be loaded with rockets: Foxfire, Gremlin, Phalanx, Thorn.', NULL, NULL, NULL, NULL, NULL, NULL, 103410, NULL, NULL, NULL, NULL, NULL),
('u', 16932, 21545, NULL, NULL, 'A powerful autocannon that can smash apart most lightly armored frigates with ease. \n\n\n\nMust be loaded with any of the following projectile ammo types: Carbonized Lead, Depleted Uranium, EMP, Fusion, Nuclear, Phased Plasma, Proton, or Titanium Sabot.', NULL, NULL, 15, NULL, NULL, NULL, 294370, NULL, NULL, NULL, NULL, 16681726),
('u', 16932, 21547, NULL, NULL, 'This artillery is one of the most powerful weapons that can be mounted on a frigate. \n\n\n\nMust be loaded with any of the following projectile ammo types: Carbonized Lead, Depleted Uranium, EMP, Fusion, Nuclear, Phased Plasma, Proton, or Titanium Sabot.', NULL, NULL, 4, NULL, NULL, NULL, 396234, NULL, NULL, NULL, NULL, 16681725),
