('u', 518, 24477, NULL, 'Thorn Javelin Rocket', 'A small rocket with a piercing warhead.\n\n\n\nA modified version of the Thorn Rocket. It can reach higher velocity than the Thorn Rocket but needs to reduce the speed of the ship to compensate.', NULL, NULL, NULL, NULL, NULL, NULL, 39.317, NULL, NULL, NULL, NULL, NULL),
('u', 518, 24478, NULL, 'Phalanx Javelin Rocket', 'A small rocket with a nuclear warhead.\n\n\n\nA modified version of the Phalanx Rocket. It can reach higher velocity than the Phalanx Rocket but needs to reduce the speed of the ship to compensate.', NULL, NULL, NULL, NULL, NULL, NULL, 36.9699, NULL, NULL, NULL, NULL, NULL),
