('u', 516, 28615, NULL, NULL, 'Skill for the operation of Electronic Attack Frigates\n\n\n\nCan not be trained on Trial Accounts.', NULL, NULL, NULL, NULL, NULL, NULL, 4024670, NULL, NULL, NULL, NULL, NULL),
('u', 4, 28617, NULL, NULL, 'A variant of the common ore Veldspar, Banidine is found in far lesser abundance - which causes no problems for miners since the latter ore is virtually worthless, being riddled with impurities.\n\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('u', 516, 28646, NULL, NULL, 'Generates an undetectable cynosural field which only Black Ops jump drives can lock on to.\n\n\n\nNote: can only be fitted on Black Ops, Covert Ops, Stealth Bombers and force Recon Ships.', NULL, NULL, NULL, NULL, NULL, NULL, 6737580, NULL, NULL, NULL, NULL, NULL),
