CREATE TEMPORARY TABLE `csn_invTypes` (
    `typeID` smallint(5) NOT NULL,
    `groupID` smallint(5) unsigned NULL,
    `typeName` TEXT CHARACTER SET utf8mb4 NULL,
    `description` TEXT CHARACTER SET utf8mb4 NULL,
    `graphicID` int(11) NULL,
    `radius` float NULL,
    `mass` float NULL,
    `volume` float NULL,
    `capacity` float NULL,
    `portionSize` int(11) NULL,
    `raceID` tinyint(2) unsigned NULL,
    `basePrice` float NULL,
    `published` bit(1) NULL,
    `marketGroupID` int(11) NULL,
    `chanceOfDuplicating` float NULL,
    `copyTypeID` int(5) NULL,
    `soundID` int(11) NULL,
    `iconID` int(11) NULL,
    `dataID` int(11) NULL,
    `typeNameID` int(11) NULL,
    `descriptionID` int(11) NULL,
    PRIMARY KEY (`typeID`)
);
    SELECT `typeID`, `groupID`, `typeName`, `description`, `graphicID`, `radius`, `mass`, `volume`, `capacity`, `portionSize`, `raceID`, `basePrice`, `published`, `marketGroupID`, `chanceOfDuplicating`, `copyTypeID`, `soundID`, `iconID`, `dataID`, `typeNameID`, `descriptionID` FROM `csn_invTypes`;
